// =============================================================================
// THUẬT TOÁN XỬ LÝ API QUẢN LÝ SINH VIÊN VÀ TÍNH TỔNG SỐ TIỀN
// Tác giả: Nguyễn Phạm Đan Linh - K59.KMT - TNUT
// =============================================================================

// 1. Dữ liệu danh sách sinh viên ban đầu (dssv)
const dssv = [
    { name: "Đan Linh", money: 123 },
    { name: "David", money: 456 },
    { name: "Thầy Cốp", money: 789 },
    { name: "Minh Anh", money: 250 },
    { name: "Văn Hoàng", money: 320 }
];

// 2. Thuật toán: Tính tổng số tiền bằng phương thức reduce
const totalMoney = dssv.reduce((sum, sv) => sum + sv.money, 0);

// 3. Thuật toán: Đếm tổng số lượng sinh viên trong danh sách
const totalStudents = dssv.length;

// 4. Thuật toán: Tìm sinh viên đóng góp / có số tiền cao nhất
let maxContributor = dssv[0];
for (let i = 1; i < dssv.length; i++) {
    if (dssv[i].money > maxContributor.money) {
        maxContributor = dssv[i];
    }
}

// 5. Chuẩn bị định dạng JSON trả về theo đúng yêu cầu đề bài giảng viên:
// - ok: 1
// - msg: "thành công"
// - dssv: mảng sinh viên gồm name và money
// Bổ sung thêm các trường thống kê (summary, total_money, count, top_student)
msg.payload = {
    ok: 1,
    msg: "thành công",
    dssv: dssv,
    summary: {
        total_students: totalStudents,
        total_money: totalMoney,
        top_student: maxContributor.name,
        currency: "VND",
        timestamp: new Date().toISOString()
    }
};

// Thiết lập Header Content-Type là JSON
msg.headers = {
    'Content-Type': 'application/json; charset=utf-8'
};

return msg;
